// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 msgValue, uint256 warpTime) public {
        vm.assume(msgValue <= 100 ether);
        vm.assume(warpTime > 0);
        vm.warp(warpTime);
        vm.roll(1);

        address actor = makeAddr("actor");
        vm.deal(actor, msgValue);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: msgValue}("");

        uint256 currentPastBlockTime = c.pastBlockTime();
        if (currentPastBlockTime > 0) {
            assertTrue(msgValue == 10 ether);
        }
    }
}
